<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class StoreOps {
 public const STATES=['new'=>'ثبت‌شده','needs_info'=>'نیازمند اطلاعات','designing'=>'در حال طراحی','awaiting_approval'=>'منتظر تأیید شما','changes'=>'اصلاح خواسته‌شده','ready'=>'آماده تحویل','packing'=>'در حال بسته‌بندی','shipped'=>'ارسال‌شده','completed'=>'تکمیل‌شده','cancelled'=>'لغوشده','returned'=>'مرجوع‌شده'];
 public static function notify(PDO $db,int $user,int $order,string $key,string $message):void {if(Db::query($db,'SELECT id FROM store_notifications WHERE dedupe=?',[$key])->fetchColumn())return;$templates=StoreSettings::get($db)['notification_templates'];$event=explode('-',$key)[0];if(isset($templates[$event])&&is_string($templates[$event]))$message=strtr($templates[$event],['{order}'=>(string)$order,'{message}'=>$message]);$notification=Db::insert($db,'store_notifications',['user_id'=>$user,'order_id'=>$order,'dedupe'=>$key,'message'=>$message,'created_at'=>date(DATE_ATOM)]);StoreDelivery::queue($db,$notification);}
 public static function owner(PDO $db,int $order):int {return (int)Db::query($db,'SELECT user_id FROM store_order_details WHERE order_id=?',[$order])->fetchColumn();}
 public static function history(PDO $db,array $actor,array $i,string $to,string $reason):void {if(StoreOperationsSchema::ready($db)){if(!Db::query($db,'SELECT item_id FROM store_item_schedule WHERE item_id=?',[$i['item_id']])->fetchColumn())Db::insert($db,'store_item_schedule',['item_id'=>$i['item_id']]);if($to==='designing')Db::query($db,'UPDATE store_item_schedule SET started_at=COALESCE(started_at,?) WHERE item_id=?',[date('Y-m-d H:i:s'),$i['item_id']]);if($to==='completed')Db::query($db,'UPDATE store_item_schedule SET completed_at=COALESCE(completed_at,?) WHERE item_id=?',[date('Y-m-d H:i:s'),$i['item_id']]);}Db::insert($db,'store_item_history',['item_id'=>$i['item_id'],'user_id'=>$actor['id'],'from_status'=>$i['status'],'to_status'=>$to,'reason'=>$reason,'created_at'=>date(DATE_ATOM)]);StoreAccess::audit($db,$actor,'item.'.$to,'item',(int)$i['item_id'],['status'=>$i['status']],['status'=>$to],$reason);}
 public static function transition(PDO $db,array $actor,int $id,string $to,int $revision,string $reason='',bool $unpaidOverride=false):void {
 Db::transaction($db,function()use($db,$actor,$id,$to,$revision,$reason,$unpaidOverride){Db::query($db,'SELECT item_id FROM store_item_details WHERE item_id=?'.StoreAccess::lock($db),[$id])->fetch();$i=StoreAccess::item($db,$id,$actor);$manager=StoreAccess::allows($db,$actor,'orders');$designer=StoreAccess::allows($db,$actor,'design')&&(int)$i['assigned_user_id']===(int)$actor['id'];$production=StoreAccess::allows($db,$actor,'production');if(!$manager&&!($designer&&in_array($to,['designing','needs_info','ready'],true))&&!($production&&in_array($to,['packing','ready','completed'],true)))throw new HttpError(403,'تغییر وضعیت مجاز نیست.');if((int)$i['revision']!==$revision)throw new HttpError(409,'نسخه ردیف سفارش تغییر کرده است.');
 $allowed=['new'=>['needs_info','designing','ready','cancelled'],'needs_info'=>['new','designing','ready','cancelled'],'designing'=>['needs_info','ready','cancelled'],'changes'=>['designing','ready','cancelled'],'awaiting_approval'=>['designing','cancelled'],'ready'=>['packing','completed','cancelled'],'packing'=>['ready'],'shipped'=>['completed','returned'],'completed'=>['returned']];if(!in_array($to,$allowed[$i['status']]??[],true))throw new HttpError(422,'این تغییر وضعیت مجاز نیست.');
 $paid=Db::query($db,"SELECT id FROM payments WHERE order_id=? AND status='verified'",[$i['order_id']])->fetchColumn();if(!$paid&&!($unpaidOverride&&$manager&&trim($reason)!==''))throw new HttpError(422,'سفارش پرداخت نشده است.');if($i['production']==='ready'&&$to==='designing')throw new HttpError(422,'کالای آماده پرونده طراحی ندارد.');if($i['delivery']==='digital'&&$to==='packing')throw new HttpError(422,'کالای دیجیتال بسته‌بندی ندارد.');
 if(in_array($to,['ready','packing','completed'],true)&&$i['production']==='custom'&&$i['approval_required']&&(!$i['latest_proof_id']||(int)$i['latest_proof_id']!==(int)$i['approved_proof_id']))throw new HttpError(422,'آخرین نسخه طرح باید توسط مشتری تأیید شود.');
 if($to==='completed'&&$i['delivery']!=='digital'&&$i['status']!=='shipped')throw new HttpError(422,'تحویل کالای فیزیکی پس از ارسال ثبت می‌شود.');
 if($to==='ready'&&$i['delivery']!=='physical'&&$i['production']==='custom'&&!Db::query($db,"SELECT id FROM store_files WHERE item_id=? AND kind='final' AND active=1",[$id])->fetchColumn())throw new HttpError(422,'فایل نهایی بارگذاری نشده است.');
 if(in_array($to,['ready','completed'],true)&&$i['delivery']!=='physical'&&!$i['download_until']){$days=Protocol::decode($i['snapshot'])['download_days']??0;if($days)Db::query($db,'UPDATE store_item_details SET download_until=? WHERE item_id=?',[time()+$days*86400,$id]);}
 if($to==='cancelled'&&$paid&&!Protocol::decode($i['snapshot'])['unlimited'])StoreCheckout::stock($db,(int)$i['variant_id'],(int)$i['quantity'],$actor,'لغو پیش از ارسال قلم #'.$id);
 if($to==='cancelled'&&$paid)foreach(Protocol::decode($i['snapshot'])['materials']??[] as $material)StoreCheckout::stock($db,(int)$material['variant_id'],(int)$material['units']*(int)$i['quantity'],$actor,'لغو رزرو ماده اولیه');
 Db::query($db,'UPDATE store_item_details SET status=?,digital_state=?,revision=revision+1,updated_at=? WHERE item_id=?',[$to,in_array($to,['ready','completed'],true)&&$i['delivery']!=='physical'?'available':$i['digital_state'],date(DATE_ATOM),$id]);self::history($db,$actor,$i,$to,$reason);self::notify($db,self::owner($db,(int)$i['order_id']),(int)$i['order_id'],'item-'.$id.'-'.($revision+1),'وضعیت «'.$i['title'].'»: '.(self::STATES[$to]??$to));self::aggregate($db,(int)$i['order_id']);});
 }
 public static function aggregate(PDO $db,int $order):void {$items=Db::query($db,'SELECT d.status,d.delivery,d.digital_state FROM store_item_details d JOIN order_items i ON i.id=d.item_id WHERE i.order_id=?',[$order])->fetchAll();$all=true;foreach($items as $i)if(!in_array($i['status'],['completed','cancelled','returned'],true))$all=false;if($items&&$all)Db::query($db,"UPDATE orders SET status='completed' WHERE id=? AND status IN('paid','preparing','partially_shipped')",[$order]);}
 public static function assign(PDO $db,array $actor,int $item,int $user,string $reason):void {StoreAccess::require($db,$actor,'orders');$i=StoreAccess::item($db,$item,$actor);if($i['production']!=='custom')throw new HttpError(422,'کالای آماده به طراح ارجاع نمی‌شود.');if($user){$u=Db::query($db,'SELECT id,role,email FROM users WHERE id=? AND active=1',[$user])->fetch();if(!$u||!StoreAccess::allows($db,$u,'design'))throw new HttpError(422,'طراح مجاز انتخاب کنید.');}Db::transaction($db,function()use($db,$actor,$item,$user,$reason,$i){Db::query($db,'UPDATE store_item_details SET assigned_user_id=?,revision=revision+1 WHERE item_id=?',[$user?:null,$item]);StoreAccess::audit($db,$actor,'assign','item',$item,['assigned_user_id'=>$i['assigned_user_id']],['assigned_user_id'=>$user],$reason);});}
 public static function approval(PDO $db,array $actor,int $item,bool $required,string $reason):void {StoreAccess::require($db,$actor,'orders');if(trim($reason)==='')throw new HttpError(422,'علت تغییر الزام تأیید لازم است.');$i=StoreAccess::item($db,$item,$actor);if($i['production']!=='custom'||in_array($i['status'],['shipped','completed'],true))throw new HttpError(422,'تغییر تأیید در این مرحله مجاز نیست.');Db::query($db,'UPDATE store_item_details SET approval_required=?,approved_proof_id=NULL,status=?,revision=revision+1 WHERE item_id=?',[$required?1:0,$i['status']==='awaiting_approval'&&!$required?'designing':$i['status'],$item]);StoreAccess::audit($db,$actor,'approval.setting','item',$item,['required'=>$i['approval_required']],['required'=>$required],$reason);}
 public static function proof(PDO $db,array $actor,int $item,int $file):int {
 return Db::transaction($db,function()use($db,$actor,$item,$file){Db::query($db,'SELECT item_id FROM store_item_details WHERE item_id=?'.StoreAccess::lock($db),[$item])->fetch();$i=StoreAccess::item($db,$item,$actor,'design');if(!$i['approval_required']||$i['production']!=='custom'||in_array($i['status'],['packing','shipped','completed','cancelled'],true))throw new HttpError(422,'تأیید مشتری برای این ردیف فعال نیست یا مرحله پایان یافته است.');if(!Db::query($db,"SELECT id FROM store_files WHERE id=? AND item_id=? AND kind='proof' AND active=1",[$file,$item])->fetchColumn())throw new HttpError(422,'فایل پیش‌نمایش معتبر نیست.');if(!Db::query($db,"SELECT id FROM payments WHERE order_id=? AND status='verified'",[$i['order_id']])->fetchColumn()&&$i['status']!=='designing')throw new HttpError(422,'پرداخت یا مجوز شروع طراحی لازم است.');$version=1+(int)Db::query($db,'SELECT MAX(version) FROM store_proofs WHERE item_id=?',[$item])->fetchColumn();$id=Db::insert($db,'store_proofs',['item_id'=>$item,'file_id'=>$file,'version'=>$version,'feedback'=>'','status'=>'pending','created_at'=>date(DATE_ATOM)]);Db::query($db,"UPDATE store_item_details SET latest_proof_id=?,approved_proof_id=NULL,status='awaiting_approval',revision=revision+1 WHERE item_id=?",[$id,$item]);self::history($db,$actor,$i,'awaiting_approval','ارسال پیش‌نمایش نسخه '.$version);self::notify($db,self::owner($db,(int)$i['order_id']),(int)$i['order_id'],'proof-'.$id,'پیش‌نمایش جدید برای تأیید شما آماده است.');return $id;});
 }
 public static function feedback(PDO $db,array $actor,int $item,int $proof,bool $approve,string $text):void {Db::transaction($db,function()use($db,$actor,$item,$proof,$approve,$text){Db::query($db,'SELECT item_id FROM store_item_details WHERE item_id=?'.StoreAccess::lock($db),[$item])->fetch();$i=StoreAccess::item($db,$item,$actor,'customer');if(!$i['approval_required']||(int)$i['latest_proof_id']!==$proof||$i['status']!=='awaiting_approval')throw new HttpError(409,'فقط آخرین پیش‌نمایش قابل پاسخ است.');$limit=(int)(Protocol::decode($i['snapshot'])['revision_limit']??0);if(!$approve&&$limit&&(int)Db::query($db,"SELECT COUNT(*) FROM store_proofs WHERE item_id=? AND status='changes'",[$item])->fetchColumn()>=$limit)throw new HttpError(422,'سقف اصلاحات مصوب این سفارش تکمیل شده؛ از بخش پیام‌ها با مدیریت هماهنگ کنید.');if(!$approve&&trim($text)==='')throw new HttpError(422,'شرح اصلاح لازم است.');Db::query($db,'UPDATE store_proofs SET status=?,feedback=? WHERE id=?',[$approve?'approved':'changes',mb_substr($text,0,5000),$proof]);Db::query($db,'UPDATE store_item_details SET approved_proof_id=?,status=?,revision=revision+1 WHERE item_id=?',[$approve?$proof:null,$approve?'designing':'changes',$item]);self::history($db,$actor,$i,$approve?'designing':'changes',$approve?'تأیید صریح آخرین پیش‌نمایش':$text);});}
 public static function message(PDO $db,array $actor,int $order,?int $item,string $text,string $kind='message',bool $internal=false,array $files=[]):int {
 if(!in_array($kind,['message','change','cancel','return','info'],true)||trim($text)===''||mb_strlen($text)>5000)throw new HttpError(422,'پیام معتبر وارد کنید.');$owner=StoreAccess::owner($db,$order,$actor);if($item){$i=StoreAccess::item($db,$item,$actor);if((int)$i['order_id']!==$order)throw new HttpError(404,'ردیف متعلق به سفارش نیست.');}elseif(!$owner&&!StoreAccess::allows($db,$actor,'orders'))throw new HttpError(404,'سفارش پیدا نشد.');if($internal&&!StoreAccess::allows($db,$actor,'orders')&&!StoreAccess::allows($db,$actor,'design'))throw new HttpError(403,'یادداشت داخلی مجاز نیست.');foreach($files as $fid){$f=StoreFiles::authorize($db,(int)$fid,$actor);if((int)$f['item_id']!==(int)$item||$f['kind']!=='message')throw new HttpError(422,'پیوست پیام معتبر نیست.');}
 $id=Db::insert($db,'store_messages',['order_id'=>$order,'item_id'=>$item,'user_id'=>$actor['id'],'kind'=>$kind,'message'=>$text,'internal'=>$internal?1:0,'files_json'=>Protocol::encode($files),'created_at'=>date(DATE_ATOM)]);if($kind==='return'&&!$internal&&StoreOperationsSchema::ready($db))StoreReturns::open($db,$actor,$order,$item,$id,$text);if(!$internal)self::notify($db,self::owner($db,$order),$order,'message-'.$id,'پیام جدید در سفارش ثبت شد.');StoreAccess::audit($db,$actor,'message.'.$kind,'order',$order,[],['message_id'=>$id,'internal'=>$internal]);return $id;
 }
 public static function ship(PDO $db,array $actor,int $order,array $in,array $quantities):int {
 StoreAccess::require($db,$actor,'shipping');return Db::transaction($db,function()use($db,$actor,$order,$in,$quantities){$o=Db::query($db,'SELECT * FROM orders WHERE id=?'.StoreAccess::lock($db),[$order])->fetch();if(!$o||!Db::query($db,"SELECT id FROM payments WHERE order_id=? AND status='verified'",[$order])->fetchColumn())throw new HttpError(422,'سفارش پرداخت‌شده لازم است.');$url=Security::text($in,'tracking_url',1000,false);if($url!==''&&(!filter_var($url,FILTER_VALIDATE_URL)||!in_array(parse_url($url,PHP_URL_SCHEME),['https','http'],true)))throw new HttpError(422,'پیوند رهگیری معتبر نیست.');$all=[];foreach(Db::query($db,'SELECT payload FROM store_shipments WHERE order_id=?',[$order])->fetchAll() as $s)foreach(Protocol::decode($s['payload']) as $id=>$q)$all[$id]=($all[$id]??0)+(int)$q;$picked=[];
 foreach($quantities as $id=>$q){$q=StoreCatalog::integer($q,0,1000000);if(!$q)continue;$id=StoreCatalog::integer($id,1);$i=StoreAccess::item($db,$id,$actor);if((int)$i['order_id']!==$order||$i['delivery']==='digital'||!in_array($i['status'],['ready','packing','shipped'],true)||($all[$id]??0)+$q>(int)$i['quantity'])throw new HttpError(422,'تعداد یا وضعیت قلم برای ارسال معتبر نیست.');if($i['approval_required']&&(!$i['latest_proof_id']||$i['approved_proof_id']!==$i['latest_proof_id']))throw new HttpError(422,'تأیید آخرین طرح لازم است.');StoreProduction::assertQuality($db,$id);$picked[$id]=$q;}
 if(!$picked)throw new HttpError(422,'حداقل یک قلم برای ارسال انتخاب کنید.');$sid=Db::insert($db,'store_shipments',['order_id'=>$order,'carrier'=>Security::text($in,'carrier',150),'tracking'=>Security::text($in,'tracking',150),'tracking_url'=>$url,'status'=>'shipped','actual_cost'=>StoreCatalog::integer($in['actual_cost']??0,0,1000000000),'payload'=>Protocol::encode($picked),'created_at'=>date(DATE_ATOM)]);
 foreach($picked as $id=>$q){$i=StoreAccess::item($db,$id,$actor);if(($all[$id]??0)+$q===(int)$i['quantity'])Db::query($db,"UPDATE store_item_details SET status='shipped',revision=revision+1 WHERE item_id=?",[$id]);self::history($db,$actor,$i,'shipped','مرسوله #'.$sid.' تعداد '.$q);}
 Db::query($db,"UPDATE orders SET status='partially_shipped' WHERE id=?",[$order]);self::notify($db,self::owner($db,$order),$order,'shipment-'.$sid,'مرسوله شما ارسال شد.');StoreAccess::audit($db,$actor,'shipment.create','order',$order,[],['shipment_id'=>$sid,'items'=>$picked]);return $sid;});
 }
 public static function delivered(PDO $db,array $actor,int $shipment):void {StoreAccess::require($db,$actor,'shipping');Db::transaction($db,function()use($db,$actor,$shipment){$s=Db::query($db,'SELECT * FROM store_shipments WHERE id=?'.StoreAccess::lock($db),[$shipment])->fetch();if(!$s||$s['status']!=='shipped')throw new HttpError(422,'مرسوله قابل تحویل نیست.');Db::query($db,"UPDATE store_shipments SET status='delivered' WHERE id=?",[$shipment]);foreach(Protocol::decode($s['payload']) as $id=>$q){$i=StoreAccess::item($db,(int)$id,$actor);$all=true;foreach(Db::query($db,'SELECT * FROM store_shipments WHERE order_id=?',[$s['order_id']])->fetchAll() as $other)if(isset(Protocol::decode($other['payload'])[$id])&&$other['status']!=='delivered')$all=false;if($all&&$i['status']==='shipped'){Db::query($db,"UPDATE store_item_details SET status='completed',revision=revision+1 WHERE item_id=?",[$id]);self::history($db,$actor,$i,'completed','تحویل مرسوله');}}self::aggregate($db,(int)$s['order_id']);StoreAccess::audit($db,$actor,'shipment.delivered','shipment',$shipment,[],[]);});}
 public static function refund(PDO $db,array $actor,int $order,int $amount,string $reason):int {StoreAccess::require($db,$actor,'finance');if($amount<1||trim($reason)==='')throw new HttpError(422,'مبلغ و علت استرداد لازم است.');return Db::transaction($db,function()use($db,$actor,$order,$amount,$reason){$o=Db::query($db,'SELECT * FROM orders WHERE id=?'.StoreAccess::lock($db),[$order])->fetch();if(!$o||!Db::query($db,"SELECT id FROM payments WHERE order_id=? AND status='verified'",[$order])->fetchColumn())throw new HttpError(422,'پرداخت تأییدشده لازم است.');$used=(int)Db::query($db,"SELECT COALESCE(SUM(amount),0) FROM store_refunds WHERE order_id=? AND status IN('requested','test_refunded')",[$order])->fetchColumn();if($used+$amount>(int)$o['total'])throw new HttpError(422,'مبلغ استرداد از مانده پرداخت بیشتر است.');$test=Env::get('APP_ENV')!=='production'&&Env::get('PAYMENT_DRIVER')==='test';$id=Db::insert($db,'store_refunds',['order_id'=>$order,'amount'=>$amount,'reason'=>$reason,'reference'=>$test?'TEST-'.bin2hex(random_bytes(8)):'','status'=>$test?'test_refunded':'requested','created_by'=>$actor['id'],'created_at'=>date(DATE_ATOM)]);if($test&&$used+$amount===(int)$o['total']){Db::query($db,"UPDATE orders SET status='refunded' WHERE id=?",[$order]);Db::query($db,"UPDATE store_item_details SET digital_state='revoked' WHERE item_id IN(SELECT id FROM order_items WHERE order_id=?)",[$order]);}StoreAccess::audit($db,$actor,'refund.'.($test?'test':'requested'),'order',$order,[],['amount'=>$amount,'refund_id'=>$id],$reason);self::notify($db,self::owner($db,$order),$order,'refund-'.$id,$test?'استرداد آزمایشی ثبت شد؛ وجه واقعی جابه‌جا نشده است.':'درخواست استرداد ثبت شد؛ عملیات بانکی هنوز انجام نشده است.');return $id;});}
}
